            const series = this._series(await this._hass.callApi('GET', query), ids).map((points, i) => {
                const factor = this._factor(ids[i]);
                return { points: points.map(p => ({ t: p.t, v: p.v * factor })), color: strings[i].color, name: strings[i].name };
            });
